<script setup lang="ts">
import {ref,onMounted,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ApiClientError} from '../../shared/api/client';
import {api,mutate,can,text,date,opts,query,useTask,type DTO,type Page} from './shared';import {authSession} from '../identity/session';import {useForm} from './forms';import TaskForm from './TaskForm.vue';import PageState from './PageState.vue';import Pager from './Pager.vue';import ProposalDialog from './ProposalDialog.vue';
const route=useRoute(),router=useRouter(),{busy,error,notice,run}=useTask(),{form,open}=useForm(),rows=ref<DTO<'Stage2ChangeCaseView'>[]>([]),selected=ref<DTO<'Stage2ChangeCaseView'>>(),items=ref<DTO<'Stage2ChangeItemView'>[]>([]),referenceNames=ref<Record<string,string>>({}),resourceFacts=ref<Record<string,DTO<'ResourceView'>>>({}),names=ref<Record<string,string>>({}),people=ref<Record<string,string>>({}),status=ref(''),mine=ref(false),page=ref(1),total=ref(0),more=ref(false),itemPage=ref(1),itemTotal=ref(0),itemMore=ref(false),proposalOpen=ref(false),editing=ref<DTO<'Stage2ChangeItemView'>>();
async function personName(id:string){try{return (await api.get<DTO<'Stage2PersonView'>>('/people/'+id)).display_name;}catch(e){if(e instanceof ApiClientError&&e.status===404)return '受限人员';throw e;}}
async function referenceName(key:string,value:string,resource:DTO<'ResourceView'>){
 if(referenceNames.value[value])return;
 let path='';
 if(key==='company_id')path='/directory/company/'+value;
 if(key==='new_contact_identity_id')path='/directory/identity/'+value;
 if(['replacement_resource_id','proposed_target_id'].includes(key))path='/resources/'+value;
 if(key==='assignment_id'){const row=resource.people.find(p=>p.assignment_id===value);if(row)referenceNames.value[value]=row.person.display_name+' · '+text(row.role);return;}
 try {
  if(path){const row=await api.get<{name:string}>(path);referenceNames.value[value]=row.name;}
  if(key==='owning_department_id'){let p=1;for(;;){const d=await api.get<Page<DTO<'Stage2DepartmentPickerOption'>>>('/departments?page_size=100&page='+p);const row=d.items.find(r=>r.id===value);if(row){referenceNames.value[value]=row.display_name;break;}if(!d.pagination.has_next)break;p++;}}
 }catch(e){if(!(e instanceof ApiClientError&&[403,404].includes(e.status)))throw e;}
}
async function details(){if(!selected.value)return;selected.value=await api.get<DTO<'Stage2ChangeCaseView'>>('/change-cases/'+selected.value.id);const d=await api.get<Page<DTO<'Stage2ChangeItemView'>>>(`/change-cases/${selected.value.id}/items?page=${itemPage.value}`);items.value=d.items;itemTotal.value=d.pagination.total;itemMore.value=d.pagination.has_next;await Promise.all(items.value.map(async i=>{const r=await api.get<DTO<'ResourceView'>>('/resources/'+i.resource_id);names.value[i.resource_id]=r.name;resourceFacts.value[i.resource_id]=r;for(const p of r.people)people.value[p.person.id]=p.person.display_name;for(const key of ['assignee_person_id','executed_by_person_id','confirmed_by_person_id']){const id=i[key as 'assignee_person_id'];if(id&&!people.value[id]){people.value[id]=await personName(id);}}for(const [key,value] of Object.entries(i.proposal)){if(typeof value==='string'&&key.endsWith('_id'))await referenceName(key,value,r);if(key.endsWith('person_id')&&typeof value==='string'&&!people.value[value]){people.value[value]=await personName(value);}}}));}
async function load(){await run(async()=>{const d=await api.get<Page<DTO<'Stage2ChangeCaseView'>>>('/change-cases'+query({status:status.value,assigned_to_me:mine.value||undefined,page:page.value}));rows.value=d.items;total.value=d.pagination.total;more.value=d.pagination.has_next;if(route.query.case)selected.value=await api.get<DTO<'Stage2ChangeCaseView'>>('/change-cases/'+route.query.case);if(selected.value)await details();});}
onMounted(load);watch([status,mine],()=>{page.value=1;void load();});
function caseForm(c?:DTO<'Stage2ChangeCaseView'>){open({title:c?'修订流程':'发起流程',description:route.query.resource?'已从资源详情进入；先建立流程，再添加具体变更事项。':'变更、交接或离职均按资源逐项执行与独立复核。',fields:[...(!c?[{key:'case_type',label:'流程类型',required:true,options:opts(['change','transfer','offboard']),initial:'change'}]:[]),{key:'reason',label:'实际原因',type:'textarea',required:true,initial:c?.reason},{key:'coordinator_person_id',label:'协调人',required:true,endpoint:'/people',initial:c?.coordinator_person_id??authSession.value?.person_id},{key:'subject_person_id',label:'交接 / 离职当事人（可选）',endpoint:'/people',initial:c?.subject_person_id??''}],onSubmit:async v=>{const d=await mutate<DTO<'Stage2ChangeCaseView'>>(c?'/change-cases/'+c.id:'/change-cases',{...v,subject_person_id:v.subject_person_id||null,...(c?{expected_version:c.version}:{})},c?'PATCH':'POST');selected.value=d;await router.replace({path:'/governance',query:{...route.query,case:d.id}});await load();}});}
function caseAction(a:string){const c=selected.value!;open({title:text(a),description:a==='submit'?'提交后提案不可随意修改。系统会保留提案基线，实际事实在独立复核后才更新。':'仅在全部事项有明确终态后关闭。有取消事项时必须说明例外。',fields:a==='close'?[{key:'closure_note',label:'关闭说明 / 例外说明',type:'textarea',required:items.value.some(i=>i.status==='cancelled')}]:[],submitLabel:text(a),onSubmit:async v=>{await mutate(`/change-cases/${c.id}/actions/${a}`,{expected_version:c.version,...(v.closure_note?{closure_note:v.closure_note}:{})});await load();}});}
async function itemAction(item:DTO<'Stage2ChangeItemView'>,a:string){let materials:DTO<'Stage2MaterialPage'>|undefined;if(a==='record-execution'){const result=await run(async()=>api.get<DTO<'Stage2MaterialPage'>>(`/resources/${item.resource_id}/materials?page_size=100`));if(!result)return;materials=result;}
 open({title:text(a),description:a==='record-execution'?'只记录真实完成的操作与实际证据，禁止填写秘密。系统不会替你在外部平台执行操作。':a==='confirm'?'请独立检查执行证据和外部结果；确认后系统才更新权威事实。':'依据实际情况操作；每次执行、退回和取消均保留历史。',fields:a==='record-execution'?[{key:'evidence_id',label:'实际执行证据',required:true,options:materials!.items.map(m=>({value:m.id,label:m.title+' · '+text(m.kind)})),hint:'没有证据时先在资源使用资料中添加说明或上传附件。'},{key:'outcome',label:'真实执行结果',required:true,options:opts(['succeeded','failed'])},{key:'non_secret_result',label:'实际操作结果说明（不含秘密）',type:'textarea',required:true,max:4000}]:a==='confirm'?[{key:'confirmation_note',label:'独立核实结论',type:'textarea',required:true}]:a==='start'?[]:[{key:'reason',label:'实际原因 / 恢复情况',type:'textarea',required:true}],submitLabel:text(a),onSubmit:async v=>{const body=a==='record-execution'?{expected_version:item.version,evidence_ids:[v.evidence_id],outcome:v.outcome,non_secret_result:v.non_secret_result}:{expected_version:item.version,...v};await mutate(`/change-items/${item.id}/actions/${a}`,body);await load();notice.value='已保存 '+text(a)+'。';}});
}
function proposed(i:DTO<'Stage2ChangeItemView'>){return Object.entries(i.proposal).map(([k,v])=>k==='action'?text(v):`${({to_person_id:'调整为',person_id:'使用人',visibility_scope:'可见范围',company_id:'归属公司',owning_department_id:'归属部门',assignment_id:'原关系',binding_id:'原绑定',new_contact_identity_id:'新身份',proposed_target_id:'新目标',operation_id:'受控操作',credential_id:'凭据',credential_grant_id:'授权',replacement_resource_id:'新密钥资源'} as Record<string,string>)[k]??k}：${typeof v==='string'?people.value[v]??referenceNames.value[v]??(v.length===36?v.slice(0,8)+'…':text(v)):text(v)}`).join('；');}
</script>
<template><header class="page-heading"><div><h1>流程治理</h1><p>类型化提案 → 实际执行与证据 → 独立复核 → 更新事实。执行人与复核人必须分离。</p></div><button v-if="can('governance.write')" class="btn-primary" @click="caseForm()">发起流程</button></header><PageState :error="error" :busy="busy" :notice="notice" @retry="load"/><p v-if="route.query.resource&&!selected" class="admin-notice admin-notice-info mb-3">已带入目标资源，请先发起流程，再添加对应事项。</p><section class="feishu-section"><div class="toolbar"><select v-model="status" class="feishu-input" aria-label="流程状态"><option value="">所有状态</option><option v-for="v in ['draft','active','completed','completed_with_exceptions','cancelled']" :value="v">{{v==='active'?'进行中':text(v)}}</option></select><label class="flex items-center gap-2 text-xs"><input v-model="mine" type="checkbox">我协调的流程</label><button class="btn-ghost ml-auto" :disabled="busy" @click="load">刷新</button></div><div class="admin-table-scroll"><table class="feishu-table min-w-[540px]"><thead><tr><th>实际原因</th><th>类型</th><th>状态</th><th>创建时间</th></tr></thead><tbody><tr v-for="c in rows" :key="c.id"><td><button class="text-link text-left font-medium" @click="selected=c;itemPage=1;router.replace({path:'/governance',query:{...route.query,case:c.id}});run(details)">{{c.reason}}</button></td><td>{{text(c.case_type)}}</td><td>{{c.status==='active'?'进行中':text(c.status)}}</td><td>{{date(c.created_at)}}</td></tr></tbody></table></div><PageState :empty="!rows.length&&!busy"/><Pager :page="page" :total="total" :more="more" @change="page=$event;load()"/></section><section v-if="selected" class="feishu-section mt-4"><header class="flex flex-wrap items-start justify-between gap-3 border-b p-4"><div><h2 class="text-base font-semibold">{{selected.reason}}</h2><p class="mt-1 text-xs text-gray-500">{{text(selected.case_type)}} · {{selected.status==='active'?'进行中':text(selected.status)}} · v{{selected.version}}</p></div><div class="flex flex-wrap gap-2"><button v-for="a in selected.available_actions" :key="a" :class="a==='submit'||a==='close'?'btn-primary':'btn-secondary'" :disabled="busy" @click="a==='edit'?caseForm(selected):a==='add-item'?(editing=undefined,proposalOpen=true):caseAction(a)">{{text(a)}}</button></div></header><div class="space-y-3 p-3"><p v-if="!items.length" class="p-3 text-sm text-gray-500">草稿尚未添加事项。每项选择一个资源与明确的变更动作。</p><article v-for="i in items" :key="i.id" class="rounded-lg border border-gray-200 p-3"><div class="flex flex-wrap items-start justify-between gap-2"><div><RouterLink :to="'/resources/'+i.resource_id" class="text-link text-sm font-medium">{{names[i.resource_id]??'查看资源'}}</RouterLink><p class="mt-1 text-xs">{{text(i.action)}} · <span class="text-gray-500">{{text(i.status)}} · v{{i.version}}</span></p></div><div class="flex flex-wrap gap-1"><button v-for="a in i.available_actions" :key="a" class="btn-secondary !px-2 !py-1 text-xs" :disabled="busy" @click="a==='edit'?(editing=i,proposalOpen=true):itemAction(i,a)">{{text(a)}}</button></div></div><div class="mt-3 grid gap-2 text-xs sm:grid-cols-2"><div class="rounded bg-gray-50 p-2"><p class="mb-1 text-gray-500">当前事实</p>{{text(resourceFacts[i.resource_id]?.lifecycle)}} · 负责人 {{resourceFacts[i.resource_id]?.owner?.display_name??'未确认'}}<p class="mt-1">使用人：{{resourceFacts[i.resource_id]?.people.filter(p=>p.role==='use'&&p.confirmation==='confirmed'&&!p.valid_to).map(p=>p.person.display_name).join('、')||'尚无确认关系'}}</p></div><div class="rounded bg-blue-50/60 p-2"><p class="mb-1 text-gray-500">拟议变更（复核前不生效）</p><p class="break-words">{{proposed(i)}}</p></div></div><dl class="mt-3 grid gap-2 text-xs sm:grid-cols-2"><div><dt class="text-gray-500">执行人</dt><dd class="mt-1">{{i.assignee_person_id?people[i.assignee_person_id]??(i.assignee_person_id===authSession?.person_id?'我':'指定执行人'):'待承接'}}</dd></div><div><dt class="text-gray-500">独立复核</dt><dd class="mt-1">{{i.confirmed_at?date(i.confirmed_at):'尚未完成'}}</dd></div></dl><RouterLink v-if="i.execution_history?.length" :to="{path:'/resources/'+i.resource_id,query:{section:'materials'}}" class="text-link mt-3 inline-block text-xs">核对执行证据与资料 →</RouterLink><p v-if="i.non_secret_result" class="mt-2 whitespace-pre-wrap break-words text-xs text-gray-600">实际结果：{{i.non_secret_result}}</p><p v-if="i.status==='awaiting_confirmation'&&i.executed_by_person_id===authSession?.person_id" class="mt-2 text-xs text-amber-700">你已记录执行，需要另一位有权限的人员独立复核。</p><details class="mt-3 text-xs"><summary class="cursor-pointer text-gray-500">提案与执行历史</summary><div class="mt-2 break-words rounded bg-gray-50 p-2"><p>{{text(i.proposal)}}</p><p v-for="(h,n) in i.execution_history" :key="n" class="mt-2">{{text(h)}}</p></div></details></article><Pager :page="itemPage" :total="itemTotal" :more="itemMore" @change="itemPage=$event;run(details)"/></div></section><ProposalDialog v-if="proposalOpen&&selected" :case-id="selected.id" :item="editing" @close="proposalOpen=false" @saved="load"/><TaskForm v-if="form" v-bind="form" @close="form=undefined"/></template>
